// Broad General American IPA per unit, from a lexicon generated by tools/build-ipa.ts
// (CMU primary pronunciations converted with the library convention; AI-generated, not
// verified against recordings).
//
// Numbers (owner, 16 Nov 2026): the IPA under a number is what the voice says. Where the line has a spoken form
// (`say`), its words for the number are used (sayAlign.ts): a phone number digit by digit ("612" → six one two),
// a price as the clip says it. Without one, readNumber() reads it as Americans say it: phone numbers and codes digit
// by digit (0 is "oh", "zero" after a +country code), prices "twelve seventy-six" / "five dollars", times "seven
// thirty", years "nineteen ninety-eight", 4th "fourth", 60% "sixty percent", 5–7 "five to seven", 3B "three B".
import LEX from "../generated/ipa-lexicon.json";
import { numberWords } from "./compose";
import { hasDigit, spokenNumbers } from "./sayAlign";

const lex = LEX as Record<string, string>;

/** Letter names (codes, seats, initialisms): the lexicon lacks several of them. */
const LETTER: Record<string, string> = {
  a: "eɪ", b: "bi", c: "si", d: "di", e: "i", f: "ɛf", g: "ʤi", h: "eɪʧ", i: "aɪ", j: "ʤeɪ", k: "keɪ", l: "ɛl", m: "ɛm",
  n: "ɛn", o: "oʊ", p: "pi", q: "kju", r: "ɑr", s: "ɛs", t: "ti", u: "ju", v: "vi", w: "ˈdʌbəlju", x: "ɛks", y: "waɪ", z: "zi",
};
/** Ordinals the lexicon lacks. */
const ORD_IPA: Record<string, string> = {
  first: "fɝst", second: "ˈsɛkənd", third: "θɝd", fourth: "fɔrθ", fifth: "fɪfθ", sixth: "sɪksθ", seventh: "ˈsɛvənθ",
  eighth: "eɪtθ", ninth: "naɪnθ", tenth: "tɛnθ", eleventh: "ɪˈlɛvənθ", twelfth: "twɛlfθ", thirteenth: "ˌθɝˈtinθ",
  fourteenth: "ˌfɔrˈtinθ", fifteenth: "ˌfɪfˈtinθ", sixteenth: "ˌsɪkˈstinθ", seventeenth: "ˌsɛvənˈtinθ",
  eighteenth: "ˌeɪˈtinθ", nineteenth: "ˌnaɪnˈtinθ", twentieth: "ˈtwɛntiəθ", thirtieth: "ˈθɝtiəθ",
};
const ORD = ["", "first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth", "eleventh", "twelfth", "thirteenth",
  "fourteenth", "fifteenth", "sixteenth", "seventeenth", "eighteenth", "nineteenth"];
const ONE_DIGIT = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"];

/** Cardinal words, any size (compose's numberWords stops at 9999; it makes the spoken forms, so it stays as it is). */
function cardinal(n: number): string[] {
  const w = (s: string) => s.split(/[\s-]+/);
  if (n < 10000) return w(numberWords(n));
  if (n < 1e6) return [...cardinal(Math.floor(n / 1000)), "thousand", ...(n % 1000 ? cardinal(n % 1000) : [])];
  return [...cardinal(Math.floor(n / 1e6)), "million", ...(n % 1e6 ? cardinal(n % 1e6) : [])];
}
function ordinal(n: number): string[] {
  if (n < 20) return [ORD[n]];
  const tens = cardinal(n - (n % 10));
  if (n % 10) return [...tens, ORD[n % 10]];
  return [...tens.slice(0, -1), tens[tens.length - 1].replace(/y$/, "ieth")];
}
const digitByDigit = (d: string, zero: "oh" | "zero" = "oh") => [...d].map((c) => (c === "0" ? zero : ONE_DIGIT[Number(c)]));
/** "two oh four", "four eighty-two", "fourteen twenty", "nineteen ninety-eight", "twenty fifteen". */
function pairs(d: string): string[] {
  const head = Number(d.slice(0, -2)), tail = Number(d.slice(-2));
  if (tail === 0) return [...cardinal(head), "hundred"];
  return [...cardinal(head), ...(tail < 10 ? ["oh", ONE_DIGIT[tail]] : cardinal(tail))];
}
const spell = (letters: string) => [...letters.toUpperCase()];

const PHONE_GROUP = /^(\+\d+|\d+)$/;
const stripTok = (t: string) => t.replace(/^[("“‘[]+/, "").replace(/[.,!?;:…)"”’\]]+$/, "");
/** A group of a phone, tracking or account number: +370, 0142, 34567, or digits next to another such group. */
function phoneLike(t: string, prev?: string, next?: string): boolean {
  if (/^\+\d+$/.test(t) || /^0\d+$/.test(t) || /^\d{5,}$/.test(t) || /^\d+(-\d+)+$/.test(t)) return true;
  if (!/^\d+$/.test(t)) return false;
  // "555 0142": another group right before (with no comma between) or right after
  const p = prev && !/[.,;:!?]$/.test(prev) ? stripTok(prev) : "";
  const n = next && !/[.,;:!?]$/.test(t) ? stripTok(next) : "";
  return (!!p && PHONE_GROUP.test(p)) || (!!n && PHONE_GROUP.test(n));
}

/** How a written number is said, without a spoken form to go by. `prev`/`next`: the written words around it. */
export function readNumber(tok: string, prev?: string, next?: string): string[] {
  const t = stripTok(tok);
  let m: RegExpExecArray | null;
  if (phoneLike(t, prev, next)) {
    const run = [prev, t, next].filter(Boolean).map((x) => stripTok(x!));
    const zero = run.some((x) => x.startsWith("+")) ? "zero" : "oh";
    return [...(t.startsWith("+") ? ["plus"] : []), ...t.replace(/^\+/, "").split("-").flatMap((g) => digitByDigit(g, zero))];
  }
  if ((m = /^\$(\d[\d,]*)(?:\.(\d\d))?$/.exec(t))) {
    const d = Number(m[1].replace(/,/g, "")), c = Number(m[2] ?? 0);
    if (!c) return [...cardinal(d), d === 1 ? "dollar" : "dollars"];
    if (!d) return [...cardinal(c), "cents"];
    return [...cardinal(d), ...(c < 10 ? ["oh", ONE_DIGIT[c]] : cardinal(c))];
  }
  if ((m = /^(\d{1,2}):(\d\d)$/.exec(t))) {
    const h = Number(m[1]), min = Number(m[2]);
    return [...cardinal(h), ...(min === 0 ? ["o'clock"] : min < 10 ? ["oh", ONE_DIGIT[min]] : cardinal(min))];
  }
  if ((m = /^(\d+)(?:st|nd|rd|th)$/.exec(t))) return ordinal(Number(m[1]));
  if ((m = /^(\d[\d,.]*)%$/.exec(t))) return [...readNumber(m[1]), "percent"];
  if ((m = /^(\d+)[–—](\d+)$/.exec(t))) return [...cardinal(Number(m[1])), "to", ...cardinal(Number(m[2]))];
  if ((m = /^'(\d\d)$/.exec(t))) return cardinal(Number(m[1]));
  if (/^\d{1,3}(,\d{3})+$/.test(t)) return cardinal(Number(t.replace(/,/g, "")));
  if ((m = /^(\d+)\.(\d+)$/.exec(t))) return [...cardinal(Number(m[1])), "point", ...digitByDigit(m[2], "zero")];
  if (/^\d+$/.test(t)) {
    const n = Number(t);
    const before = (prev ?? "").toLowerCase().replace(/[^a-z]/g, "");
    if (t.length === 4 && n >= 1100 && n < 2100 && !(n >= 2000 && n < 2010)) return pairs(t); // a year
    if (t.length >= 3 && /^(flight|code|pin|extension|ext)$/.test(before)) return digitByDigit(t);
    if (t.length >= 3 && /^(room|suite|apartment|apt|bus|route|gate)$/.test(before)) return pairs(t);
    return cardinal(n);
  }
  // codes: HH-4471, NW-48213 (letters by name, digits one by one), seats and spots: 12A, B4 (a number and a letter)
  if ((m = /^([A-Z]+)-(\d+)$/.exec(t))) return [...spell(m[1]), ...digitByDigit(m[2])];
  if ((m = /^([A-Z]{1,2})(\d{1,2})$/.exec(t))) return [...spell(m[1]), ...cardinal(Number(m[2]))];
  if ((m = /^(\d{1,3})([A-Z])$/.exec(t))) return [...cardinal(Number(m[1])), m[2]];
  if ((m = /^(\d+)-(\p{L}+)$/u.exec(t))) return [...cardinal(Number(m[1])), m[2].toLowerCase()];
  // anything else: its letters as a word, its digits one by one (a password "sunnycup22")
  return (t.match(/\d+|\p{L}+/gu) ?? []).flatMap((p) => (/\d/.test(p) ? digitByDigit(p) : [p.toLowerCase()]));
}

function wordIpa(w: string): string {
  // a capital letter on its own is the letter's name (seat 12A, "H, H, four…"), not the article "a"
  if (/^[A-Z]$/.test(w)) return LETTER[w.toLowerCase()];
  const l = w.replace(/’/g, "'").toLowerCase();
  return lex[l] ?? ORD_IPA[l] ?? lex[l.replace(/'s$/, "")] ?? "";
}

/** The spoken words of one written word (not a number). */
function plainWords(tok: string): string[] {
  const out: string[] = [];
  for (const part of tok.split(/[—–]+|-(?=[A-Za-z])/)) {
    const raw = part.replace(/^[^\p{L}0-9'’]+|[^\p{L}0-9'’]+$/gu, "").replace(/’/g, "'");
    // an initialism (US, ID, ATM): letter by letter
    if (/^[A-Z]{2,4}$/.test(raw) && (INITIALISMS.has(raw) || !lex[raw.toLowerCase()])) { out.push(...spell(raw)); continue; }
    const w = unquote(raw.toLowerCase());
    if (w) out.push(w);
  }
  return out;
}
/** Capitals said letter by letter even though the lexicon has a word spelled the same. */
const INITIALISMS = new Set(["US", "ID", "IT", "AM", "PM", "TV", "OK", "DJ", "PC", "UK", "EU", "CV", "PIN", "ATM", "DMV", "USA", "ER", "IV", "MD"]);

/** A word in quotation marks ("'I regret to inform you'") loses the marks; contractions ('cause, 'em) and plural
 *  possessives (parents') keep their apostrophe. */
function unquote(w: string): string {
  if (w.startsWith("'") && !/^'(cause|em|til|bout|n|tis|twas|round|\d\d)$/.test(w)) w = w.slice(1);
  if (w.endsWith("'") && !/s'$/.test(w)) w = w.slice(0, -1);
  // what was inside the quotes may end in punctuation of its own ("'I was wrong.'")
  return w.replace(/^[^\p{L}0-9']+|[^\p{L}0-9']+$/gu, "");
}

const ipaOf = (words: string[]) => words.flatMap((w) => w.split(/-(?=\p{L})/u)).map(wordIpa).filter(Boolean).join(" ");

/** IPA for each unit of a sentence; numbers as the line's spoken form (`say`) says them. */
export function ipaForSentence(units: string[], say?: string): string[] {
  const toks = units.map((u) => u.split(/\s+/).filter(Boolean));
  const flat = toks.flat();
  const spoken = spokenNumbers(flat, say);
  let k = 0;
  return toks.map((ws) => ipaOf(ws.flatMap((w) => {
    const i = k++;
    if (!hasDigit(w)) return plainWords(w);
    return spoken[i] ?? readNumber(w, flat[i - 1], flat[i + 1]);
  })));
}

/** IPA for a unit on its own (a card): numbers by readNumber. */
export function ipaForUnit(en: string): string {
  return ipaForSentence([en])[0];
}

export const hasIpa = () => Object.keys(lex).length > 0;
